gG7(){return"\u0410\u043a\u0442\u0438\u0432\u043d\u043e\u0457 \u0441\u043a\u0430\u0440\u0433\u0438 \u043d\u0435\u043c\u0430\u0454. \u041f\u043e\u043a\u0438 \u0434\u0456\u0454 \u0441\u0442\u0440\u043e\u043a \u043f\u043e\u0434\u0430\u043d\u043d\u044f, \u0457\u0457 \u043c\u043e\u0436\u0435 \u0432\u0456\u0434\u043a\u0440\u0438\u0442\u0438 \u0431\u0443\u0434\u044c-\u044f\u043a\u0430 \u0441\u0442\u043e\u0440\u043e\u043d\u0430."},
